// Regenerates programs/private_presale/src/verifying_keys.rs from the
// circuit keys built in ../protocol (run `npm run circuits` there first).
const fs = require("fs");
const path = require("path");
const { vkeyToRust } = require("../lib/proof");

const circuits = path.join(__dirname, "..", "..", "protocol", "build", "circuits");
const read = (n) => JSON.parse(fs.readFileSync(path.join(circuits, `${n}_vkey.json`), "utf8"));

const out = [
  "//! Generated by solana/scripts/verifying-keys.js from protocol/build/circuits. Do not edit.",
  "//! These come from the local development trusted setup and must be regenerated",
  "//! after a real multi-party ceremony.",
  "use groth16_solana::groth16::Groth16Verifyingkey;",
  "",
  vkeyToRust("ELIGIBILITY_VK", read("eligibility")),
  "",
  vkeyToRust("CLAIM_VK", read("claim")),
  "",
].join("\n");

const target = path.join(__dirname, "..", "programs", "private_presale", "src", "verifying_keys.rs");
fs.writeFileSync(target, out);
console.log("wrote", path.relative(process.cwd(), target));
